function doPrint(title,html,myNotes){const nH=myNotes&&myNotes.length?`<div style="margin-top:14px;border-top:2px solid #ddd;padding-top:8px"><h3 style="color:#B45309">הערות</h3>${myNotes.map(n=>`<div style="background:#f9f9f9;padding:6px;border-radius:5px;margin-bottom:5px;border:1px solid #eee"><small style="color:#888">${esc(n.ts)}</small>${n.text?`<p>${esc(n.text)}</p>`:""}${n.images&&n.images.length?`<div style="display:flex;gap:3px;margin-top:3px">${n.images.map(i=>`<img src="${i}" style="width:70px;height:70px;object-fit:cover;border-radius:3px"/>`).join("")}</div>`:""}</div>`).join("")}</div>`:"";const docHtml=(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>${title}</title><style>body{font-family:Arial,sans-serif;max-width:660px;margin:25px auto;padding:0 18px;color:#1a1a1a;line-height:1.6}h1{color:#B45309;border-bottom:3px solid #F59E0B;padding-bottom:6px;font-size:18px}h2,h3{color:#92400E;font-size:15px}.hdr,.ftr{text-align:center;padding:12px;border:2px solid #F59E0B;border-radius:10px;margin-bottom:16px}.hdr{background:#FFF8E7}.ftr{margin-top:20px;background:#FFF8E7;font-size:11px}@media print{body{margin:8px}}</style></head><body><div class="hdr"><h2 style="margin:0;color:#B45309">🔧 ${ABOUT.title}</h2><p style="margin:4px 0 0;color:#92400E;font-size:12px">${ABOUT.creator}</p></div><h1>${title}</h1>${html}${nH}<div class="ftr"><strong style="color:#B45309">🔧 ${ABOUT.title}</strong><br/>${ABOUT.creator}<br/>${ABOUT.copy}<br/><a href="${ABOUT.link}">${ABOUT.link}</a></div></body></html>`);printViaFrame(docHtml);}
function printViaFrame(docHtml){
  try{
    const old=document.getElementById("adp-print-frame"); if(old) old.remove();
    const f=document.createElement("iframe"); f.id="adp-print-frame"; f.setAttribute("aria-hidden","true");
    f.style.cssText="position:fixed;width:0;height:0;border:0;left:-9999px;top:0";
    document.body.appendChild(f);
    const d=f.contentWindow.document; d.open(); d.write(docHtml); d.close();
    const go=()=>{try{f.contentWindow.focus();f.contentWindow.print();}catch(e){window.dispatchEvent(new CustomEvent("adp-toast",{detail:"ההדפסה לא נתמכת במכשיר הזה"}));}};
    const imgs=Array.from(d.images||[]); let left=imgs.filter(i=>!i.complete).length;
    if(!left) setTimeout(go,300); else { const done=()=>{if(--left<=0) setTimeout(go,200);}; imgs.forEach(i=>{if(!i.complete){i.onload=done;i.onerror=done;}}); setTimeout(()=>{if(left>0){left=0;go();}},3000); }
  }catch(e){ window.dispatchEvent(new CustomEvent("adp-toast",{detail:"ההדפסה לא נתמכת במכשיר הזה"})); }
}
